import{Nt as e,_t as t,ft as n,gt as r,ht as i,kt as a,s as o,vt as s}from"./chunks/framework.T4koa5Cm.js";var c=JSON.parse(`{"title":"VMTU文档","description":"","frontmatter":{},"headers":[],"relativePath":"vmtu/index.md","filePath":"vmtu/index.md"}`),l={name:`vmtu/index.md`};function u(o,c,l,u,d,f){let p=e(`MediumLinkCard`);return a(),i(`div`,null,[c[0]||=n(`h1`,{id:`vmtu文档`,tabindex:`-1`},[t(`VMTU文档 `),n(`a`,{class:`header-anchor`,href:`#vmtu文档`,"aria-label":`Permalink to “VMTU文档”`},`​`)],-1),c[1]||=n(`p`,null,`VMTU是一个为 Minecraft 整合包汉化补丁设计的自动化汉化管理工具，涵盖了绝大部分汉化相关的使用场景。`,-1),c[2]||=n(`p`,null,`普通玩家可以通过它获得额外的模组资源包汉化，VM汉化组内部也可以通过它为玩家提供更好的汉化体验。`,-1),c[3]||=n(`div`,{class:`important custom-block github-alert`},[n(`p`,{class:`custom-block-title`},`重要提示`),n(`p`,null,`本文档所有内容基于 VMTU 最新版 5.2.3 编写。 MC 1.12.2版本的 VMTU 配置文件为 cfg 格式，与文档演示的toml格式存在较大差异，请以游戏内实际为准`)],-1),s(p,{title:`Github`,desc:`Mod主仓库`,href:`https://github.com/VM-Chinese-translate-group/VMTranslationUpdateMod`,iconify:`simple-icons:github`,external:!0}),s(p,{title:`Github`,desc:`VMTULibraries`,href:`https://github.com/VM-Chinese-translate-group/VMTULibraries`,iconify:`simple-icons:github`,external:!0}),s(p,{title:`Github`,desc:`VM-Resources`,href:`https://github.com/VM-Chinese-translate-group/VM-Resources`,iconify:`simple-icons:github`,external:!0}),s(p,{title:`CurseForge`,href:`https://www.curseforge.com/minecraft/mc-mods/vmtu`,iconify:`simple-icons:curseforge`,iconifyColor:`#f1693c`,external:!0}),s(p,{title:`Modrinth`,href:`https://modrinth.com/mod/vmtu`,iconify:`selfhst:modrinth`,external:!0}),c[4]||=r(`<h2 id="模组功能" tabindex="-1">模组功能 <a class="header-anchor" href="#模组功能" aria-label="Permalink to “模组功能”">​</a></h2><p>模组的所有功能都是可配置的，关于配置文件及更详细的功能介绍请看后文。</p><ul><li>✅ 自动检测汉化版本更新，并在游戏里通知玩家更新。</li><li>📥 自动下载并激活汉化资源包</li><li>🌐 自动切换游戏语言</li><li>📦 指定整合包配置文件，支持为每个包指定自身汉化策略</li><li>🚦 指定资源包加载顺序</li><li>🔍 支持检测 I18nUpdateMod、Vault Patcher、Texture Locale Redirector 模组是否缺失。如未安装将弹出提示页面引导下载</li></ul><p>其中，自动下载并激活资源包功能（VMTULibraries-ResourcePack）的代码源于 i18nUpdateMod3<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> 模组代码修改，按照上游协议规定使用 AGPL v3 协议。</p><h2 id="版本支持情况" tabindex="-1">版本支持情况 <a class="header-anchor" href="#版本支持情况" aria-label="Permalink to “版本支持情况”">​</a></h2><p>本模组需要 Cloth Config API 作为前置（1.12.2版本除外），支持 Forge、NeoForge 和 Fabric 三大主流模组加载器。</p><p>VMTU 目前同时支持和维护以下的全版本，以下是支持版本列表：</p><table tabindex="0"><thead><tr><th>模组加载器</th><th>支持的 Minecraft 版本</th></tr></thead><tbody><tr><td>Forge</td><td>1.12.2<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup>/1.16.5/1.18~1.20.4<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></td></tr><tr><td>NeoForge</td><td>1.20~26.2</td></tr><tr><td>Fabric</td><td>1.16.5~26.2</td></tr></tbody></table><h2 id="开源协议" tabindex="-1">开源协议 <a class="header-anchor" href="#开源协议" aria-label="Permalink to “开源协议”">​</a></h2><p>开源协议：MIT（VMTUMod）、AGPL v3（VMTULibraries-ResourcePack）、LGPL v3（VMTULibraries-Common、VMTULibraries-Modpack）</p><p>其中，VMTULibraries仓库包含3个子库：</p><ul><li>Common: VMTU通用代码库</li><li>ResourcePack: VMTU资源包库，用于管理汉化资源包的下载和激活。</li><li>Modpack: VMTU整合包库，用于管理整合包版本及其汉化补丁版本。</li></ul><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>i18nUpdateMod3是由CFPA制作的模组，提供了自动下载更新资源包的功能，VMTU的相关功能基于其代码修改而来。 <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>注：1.12.2 版本以后将不再更新主要版本（VMTU 6.0.0），将停留在 5.x 版本系列。 <a href="#fnref2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p>注：对于 Forge 端 1.20.5 及以上版本，由于模组的前置依赖 Cloth Config API 已不再支持，故本模组也不支持。 <a href="#fnref3" class="footnote-backref">↩︎</a></p></li></ol></section>`,14)])}var d=o(l,[[`render`,u]]);export{c as __pageData,d as default};